leave_own_history_v1.definition:
CREATE FUNCTION public.leave_own_history_v1(p_before bigint DEFAULT NULL,p_limit integer DEFAULT 25) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=private.ihr_leave_require_personal_actor();rows jsonb;next_before bigint;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100 OR (p_before IS NOT NULL AND p_before<1) THEN RAISE EXCEPTION 'Invalid history page' USING ERRCODE='22023',DETAIL='{"code":"INVALID_HISTORY_PAGE"}'; END IF;
 SELECT coalesce(jsonb_agg(s.entry ORDER BY s.sequence DESC),'[]'),min(s.sequence) INTO rows,next_before FROM (
  SELECT r.sequence,private.ihr_leave_request_summary(r) entry FROM public.ihr_leave_requests r
  WHERE r.employee_id=actor AND (p_before IS NULL OR r.sequence<p_before) ORDER BY r.sequence DESC LIMIT p_limit
 ) s;
 IF NOT EXISTS(SELECT 1 FROM public.ihr_leave_requests r WHERE r.employee_id=actor AND r.sequence<next_before) THEN next_before:=NULL; END IF;
 RETURN jsonb_build_object('rows',rows,'nextBefore',next_before);
END;
$$;

leave_balance_history_v1.definition:
CREATE FUNCTION public.leave_balance_history_v1(p_account_id uuid,p_before bigint DEFAULT NULL,p_limit integer DEFAULT 25) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=private.ihr_leave_require_actor();a public.ihr_leave_accounts%ROWTYPE;rows jsonb;next_before bigint;
BEGIN
 SELECT * INTO a FROM public.ihr_leave_accounts WHERE id=p_account_id;
 IF a.id IS NULL OR NOT ((a.employee_id=actor AND EXISTS(SELECT 1 FROM public.ihr_leave_members m WHERE m.user_id=actor AND m.active AND m.member_kind IN('employee','manager')))
  OR private.ihr_leave_has_grant(actor,'read_private',a.employee_id)) THEN
  RAISE EXCEPTION 'Balance access denied' USING ERRCODE='42501',DETAIL='{"code":"BALANCE_ACCESS_DENIED"}'; END IF;
 IF p_limit IS NULL OR p_limit<1 OR p_limit>100 OR (p_before IS NOT NULL AND p_before<1) THEN RAISE EXCEPTION 'Invalid history page' USING ERRCODE='22023',DETAIL='{"code":"INVALID_HISTORY_PAGE"}'; END IF;
 SELECT coalesce(jsonb_agg(r.entry ORDER BY r.sequence DESC),'[]'),min(r.sequence) INTO rows,next_before FROM (
  SELECT l.sequence,jsonb_build_object('id',l.id,'sequence',l.sequence,'date',l.effective_date,'kind',l.kind,
   'allowanceDelta',l.allowance_delta,'reservedDelta',l.reserved_delta,'usedDelta',l.used_delta) entry
  FROM public.ihr_leave_ledger l WHERE l.account_id=a.id AND (p_before IS NULL OR l.sequence<p_before) ORDER BY l.sequence DESC LIMIT p_limit
 ) r;
 IF NOT EXISTS(SELECT 1 FROM public.ihr_leave_ledger l WHERE l.account_id=a.id AND l.sequence<next_before) THEN next_before:=NULL; END IF;
 RETURN jsonb_build_object('balance',private.ihr_leave_balance_json(a,statement_timestamp()),'rows',rows,'nextBefore',next_before);
END;
$$;

leave_calendar_v1.definition:
CREATE FUNCTION public.leave_calendar_v1(p_from date,p_to date,p_audience text DEFAULT 'own') RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=private.ihr_leave_require_actor();authorized_at timestamptz:=statement_timestamp();rows jsonb;
BEGIN
 IF p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to)
  OR p_from>p_to OR p_to-p_from>92 OR p_audience IS NULL OR p_audience NOT IN('own','assigned_team','granted') THEN
  RAISE EXCEPTION 'Invalid calendar range or audience' USING ERRCODE='22023';
 END IF;
 -- Audience authorization precedes row lookup, so guessed ranges cannot distinguish access.
 IF NOT EXISTS(SELECT 1 FROM public.ihr_leave_members m
  WHERE private.ihr_leave_calendar_can_read(actor,m.user_id,p_audience,authorized_at)) THEN
  RAISE EXCEPTION 'Calendar access denied' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object(
  'employeeId',r.employee_id,'employeeName',u.full_name,'date',to_char(d.day,'YYYY-MM-DD'),
  'approvedMinutes',d.charged_minutes,'availabilityLabel',
  CASE WHEN d.charged_minutes=d.scheduled_minutes THEN 'full_scheduled_absence' ELSE 'partial_absence' END)
  ORDER BY d.day,u.full_name,r.employee_id),'[]'::jsonb) INTO rows
 FROM public.ihr_leave_requests r JOIN public.ihr_leave_request_days d ON d.request_id=r.id
 JOIN public.users u ON u.id=r.employee_id
 WHERE r.status IN('approved','cancellation_pending') AND d.charged_minutes>0 AND d.day BETWEEN p_from AND p_to
  AND private.ihr_leave_calendar_can_read(actor,r.employee_id,p_audience,authorized_at);
 RETURN rows;
END;
$$;

leave_approval_counts_v1.definition:
CREATE FUNCTION public.leave_approval_counts_v1() RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=private.ihr_leave_require_actor();authorized_at timestamptz:=statement_timestamp();pending_leave bigint;pending_cancellation bigint;
BEGIN
 SELECT count(*) FILTER (WHERE r.status='submitted'),count(*) FILTER (WHERE r.status='cancellation_pending')
 INTO pending_leave,pending_cancellation FROM public.ihr_leave_requests r
 WHERE private.ihr_leave_is_assigned_request(actor,r.id,authorized_at);
 RETURN jsonb_build_object('pendingLeave',pending_leave,'pendingCancellation',pending_cancellation);
END;
$$;

leave_hr_request_history_v1.definition:
CREATE FUNCTION public.leave_hr_request_history_v1(p_employee_id uuid,p_request_id uuid,p_before_at timestamptz DEFAULT NULL,p_before_id uuid DEFAULT NULL,p_limit integer DEFAULT 25) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$
DECLARE actor uuid:=private.ihr_leave_require_hr_reader(p_employee_id);r public.ihr_leave_requests%ROWTYPE;rows jsonb;cursor jsonb;last_at timestamptz;last_id uuid;
BEGIN
 SELECT * INTO r FROM public.ihr_leave_requests WHERE id=p_request_id AND employee_id=p_employee_id;
 IF r.id IS NULL THEN RAISE EXCEPTION 'Request access denied' USING ERRCODE='42501',DETAIL='{"code":"REQUEST_ACCESS_DENIED"}';END IF;
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 50 OR (p_before_at IS NULL)<>(p_before_id IS NULL) OR (p_before_at IS NOT NULL AND NOT isfinite(p_before_at)) THEN RAISE EXCEPTION 'Invalid history page' USING ERRCODE='22023';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',e.id,'event',e.event,'atTime',e.at_time,'actor',jsonb_build_object('id',e.actor_id,'name',u.full_name),
  'reason',CASE WHEN e.event='reassigned' THEN reassignment.reason WHEN e.event IN('rejected','cancellation_requested','cancellation_declined') AND jsonb_typeof(e.data->'reason')='string' THEN e.data->>'reason' ELSE NULL END,
  'approverName',CASE WHEN e.event IN('submitted','opening_imported') THEN r.approver_name WHEN e.event='reassigned' THEN reassignment.assignment_source->>'approver_name'
   WHEN e.event IN('cancellation_requested','cancellation_accepted','cancellation_declined') THEN attempt.approver_name
   WHEN e.event IN('approved','rejected') THEN coalesce(decision_route.assignment_source->>'approver_name',r.approver_name) ELSE NULL END) ORDER BY e.at_time DESC,e.id DESC),'[]') INTO rows
 FROM(SELECT * FROM private.ihr_leave_request_events WHERE request_id=p_request_id AND (p_before_at IS NULL OR (at_time,id)<(p_before_at,p_before_id)) ORDER BY at_time DESC,id DESC LIMIT p_limit)e
 JOIN public.users u ON u.id=e.actor_id
 LEFT JOIN private.ihr_leave_request_reassignments reassignment ON e.event='reassigned' AND reassignment.request_id=r.id AND reassignment.request_version::text=e.data->>'requestVersion'
 LEFT JOIN private.ihr_leave_cancellation_attempts attempt ON attempt.request_id=r.id AND attempt.id::text=e.data->>'attemptId'
 LEFT JOIN LATERAL(SELECT rr.assignment_source FROM private.ihr_leave_request_reassignments rr WHERE rr.request_id=r.id AND rr.created_at<=e.at_time ORDER BY rr.request_version DESC LIMIT 1)decision_route ON e.event IN('approved','rejected');
 IF jsonb_array_length(rows)>0 THEN
  last_at:=(rows->(jsonb_array_length(rows)-1)->>'atTime')::timestamptz;last_id:=(rows->(jsonb_array_length(rows)-1)->>'id')::uuid;
  IF EXISTS(SELECT 1 FROM private.ihr_leave_request_events WHERE request_id=p_request_id AND (at_time,id)<(last_at,last_id)) THEN cursor:=jsonb_build_object('atTime',last_at,'id',last_id);END IF;
 END IF;
 RETURN jsonb_build_object('employeeId',p_employee_id,'requestId',p_request_id,'scopeVersion',private.ihr_leave_scope_version(actor),'authorityKey',private.ihr_leave_admin_authority_key(actor,p_employee_id),'rows',rows,'nextBefore',cursor);
END;
$$;
